WITH remaining_keys AS (SELECT device_code, firmware FROM device_readings INTERSECT ALL SELECT device_code, firmware FROM device_readings WHERE humidity BETWEEN 38 AND 41), verified AS (SELECT s.* FROM device_readings s INNER JOIN remaining_keys k ON s.device_code = k.device_code AND s.firmware = k.firmware) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, CASE WHEN status_bits >= 11 THEN 'HIGH' ELSE 'LOW' END AS status_bits_tier, DATE_TRUNC('DAY', reading_ts) AS activity_day, ROUND(AVG(pressure), 2) AS avg_pressure, SUM(CASE WHEN device_code = 'DV-03' THEN status_bits ELSE 0 END) AS dv_03_status_bits, MIN(reading_ts) AS started_at FROM verified GROUP BY DATE_TRUNC('HOUR', reading_ts), CASE WHEN status_bits >= 11 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('DAY', reading_ts) ORDER BY status_bits_tier DESC;
